200|    pulse(img instanceof HTMLElement ? img : null);
201|  }
202|
203|  // Every pager move runs through navReducer; a new scene id means a
204|  // route push, a same-scene result means a client sub-page move.
205|  function move(action: NavAction) {
206|    pic.hidePopover();
207|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
208|    if (next.sceneId !== view.sceneId) {
209|      hasNavigated = true;
210|      if (next.page > 0) enterAtEnd = true;
211|      router.push(`/leer/${next.sceneId}`);
212|      return;
213|    }
214|    if (next.page !== page) {
215|      setPage(next.page);
216|      readColRef.current?.scrollTo(0, 0);
217|    }
218|  }
219|
220|  function goNext() {
221|    move({ kind: "next" });
222|  }
223|
224|  function goPrev() {
225|    move({ kind: "prev" });
226|  }
227|
228|  // Scene entry resets orientation; sub-page moves keep the heading.
229|  useEffect(() => {
230|    if (hasNavigated) headingRef.current?.focus();
231|    readColRef.current?.scrollTo(0, 0);
232|  }, [view.sceneId]);
233|
234|  useEffect(() => {
235|    const onKey = (event: KeyboardEvent) => {
236|      if (event.metaKey || event.ctrlKey || event.altKey) return;
237|      const target = event.target as HTMLElement | null;
238|      if (
239|        target &&
240|        (target.tagName === "INPUT" ||
241|          target.tagName === "SELECT" ||
242|          target.tagName === "TEXTAREA" ||
243|          target.isContentEditable)
244|      ) {
245|        return;
246|      }
247|      if (event.key === "ArrowRight") {
248|        event.preventDefault();
249|        goNext();
250|      } else if (event.key === "ArrowLeft") {
251|        event.preventDefault();
252|        goPrev();
253|      } else if (
254|        event.key === " " ||
255|        event.key === "PageDown" ||
256|        event.key === "ArrowDown" ||
257|        event.key === "PageUp" ||
258|        event.key === "ArrowUp"
259|      ) {
260|        if (target !== null && target.tagName === "BUTTON") return;
261|        const forward =
262|          event.key === "PageDown" || event.key === "ArrowDown" || (event.key === " " && !event.shiftKey);
