264|        const col = readColRef.current;
265|        if (col !== null) {
266|          const at = edges(col);
267|          if ((forward && !at.atBottom) || (!forward && !at.atTop)) {
268|            col.scrollBy({ top: (forward ? 1 : -1) * col.clientHeight * 0.85, behavior: "smooth" });
