280|  // Wheel and trackpad turn pages: at a column edge, an accumulated swipe
281|  // calls goNext/goPrev. preventDefault only on a turn, so the column
282|  // keeps scrolling natively until it rests on its edge.
283|  useEffect(() => {
284|    const onWheel = (event: WheelEvent) => {
285|      if (panelsOpen || gateOpen || pic.lightbox.item !== null) return;
286|      if (event.ctrlKey) return;
287|      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
288|      const target = event.target instanceof HTMLElement ? event.target : null;
289|      const readCol = readColRef.current;
290|      if (inNestedScroller(target, readCol)) return;
291|      const at = readCol === null ? { atTop: true, atBottom: true } : edges(readCol);
