309|    return () => window.removeEventListener("wheel", onWheel);
310|  }, [page, view.sceneId, index, router, panelsOpen, gateOpen, pic.lightbox.item]);
311|
312|  return (
313|    <>
314|      <ImagePane
315|        // The cover always shows the placeholder: nothing to picture yet,
316|        // and a cached scene picture would spoil the chapter.
317|        card={kind === "cover" ? { phase: "idle" } : pic.card}
318|        onPicture={() => pic.illustrateScene()}
319|        onRetry={() => pic.illustrateScene()}
320|        onClear={pic.clearScene}
321|        onOpen={pic.lightbox.open}
322|        bare={kind === "cover"}
323|        onPictureChapter={
324|          kind === "cover" ? null : kind === "end" ? () => setPanelsOpen(true) : requestPanels
325|        }
326|      />
327|      <Divider />
328|      <div className="read-col" ref={readColRef} aria-label="Reading column">
329|        {kind === "cover" ? (
330|          <>
331|            <div className="kicker">Chapter</div>
332|            <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${view.ch}`}>
333|              {view.ch}
334|            </p>
335|            <h1
336|              className="chapter-title cover-title"
337|              data-long={coverLong}
338|              id="scene-heading"
339|              ref={headingRef}
340|              tabIndex={-1}
341|            >
342|              {view.chapterTitle}
343|            </h1>
344|            <hr className="cover-rule" />
345|            {offerAside ? (
346|              <PanelsQuietLink onOpen={requestPanels} />
347|            ) : (
348|              <PanelsOfferCard panels={panels} onShowAnyway={showAnyway} onReadFirst={readFirst} />
349|            )}
350|            <button type="button" className="cover-begin" onClick={goNext}>
351|              Begin the chapter →
352|            </button>
353|            <span className="read-on-hint">or just scroll</span>
354|          </>
355|        ) : kind === "end" ? (
356|          <>
357|            <div className="kicker">End of Chapter {view.ch}</div>
358|            <div className="end-card">
359|              <BlurredThumbs panels={panels} unblurredCount={Math.min(4, panels.length)} />
360|              <h2>Relive this chapter in panels</h2>
361|              <div className="panels-btns">
362|                <button type="button" className="panels-primary" onClick={() => setPanelsOpen(true)}>
363|                  Open the panels
364|                </button>
365|              </div>
366|            </div>
367|            {nextChapter ? (
368|              <button type="button" className="end-next" onClick={goNextChapter}>
369|                On to Chapter {nextChapter.ch} →
370|              </button>
371|            ) : (
372|              <p className="the-end">The end.</p>
373|            )}
374|          </>
375|        ) : (
376|          <>
377|            <div className="kicker">Chapter {view.ch}</div>
378|            <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
379|              {view.chapterTitle}
380|            </h1>
381|            <div className="scene-line">
382|              <span>
383|                Scene {view.k} of {view.n}
384|                {view.pages.length > 1 ? ` · Page ${textIndex + 1} of ${view.pages.length}` : ""}
385|              </span>
386|            </div>
387|            <div className={`body-text${textIndex === 0 ? " dropcap" : ""}`} ref={pic.viewRef}>
388|              {sub?.paragraphs.map((p, i, arr) => (
389|                <Fragment key={p.id}>
390|                  <p id={p.id} data-n={p.n} data-cont={p.cont ? true : undefined}>
391|                    {p.text}
392|                  </p>
393|                  {/* A figure for n lands after its last visible fragment. */}
394|                  {figuresAfter(arr, i, figsByN).map((fig) => (
395|                    <InlineFigureView
396|                      key={fig.id}
397|                      figure={fig}
398|                      onRemove={() => pic.removeFigure(fig.id)}
399|                      onRetry={() => pic.retryFigure(fig.id)}
400|                      onOpen={pic.lightbox.open}
401|                      refCb={(el) => {
